using OOP_FINAL_CSharp.Models;
using OOP_FINAL_CSharp.Models.Enums;
using OOP_FINAL_CSharp.Models.Policy;

namespace OOP_FINAL_CSharp.Services;

/// <summary>
/// In-memory hotel service. IDs for newly-created customers, room groups,
/// utilities, and rooms are generated by the service. Add* methods also reject
/// blank or duplicate IDs so callers cannot bypass uniqueness checks.
/// </summary>
public sealed class HotelService
{
    private readonly List<Customer> _customers = [];
    private readonly List<RoomGroup> _roomGroups = [];
    private readonly List<Utility> _utilities = [];
    private readonly List<Room> _rooms = [];
    private readonly List<RentalContract> _contracts = [];
    private readonly List<Invoice> _invoices = [];

    private int _invoiceCounter;
    private int _contractCounter;

    public IReadOnlyList<Customer> Customers => _customers.AsReadOnly();
    public IReadOnlyList<RoomGroup> RoomGroups => _roomGroups.AsReadOnly();
    public IReadOnlyList<Utility> Utilities => _utilities.AsReadOnly();
    public IReadOnlyList<Room> Rooms => _rooms.AsReadOnly();
    public IReadOnlyList<RentalContract> Contracts => _contracts.AsReadOnly();
    public IReadOnlyList<Invoice> Invoices => _invoices.AsReadOnly();

    // ---------- ID-generating creation methods ----------

    public Customer CreateCustomer(string name, string phoneNumber, string cccd, CustomerType type)
    {
        var id = GenerateId("KH", _customers.Select(c => c.Id));
        var customer = new Customer(id, name, phoneNumber, cccd, type);
        if (!AddCustomer(customer))
            throw new InvalidOperationException($"Could not register generated customer ID '{id}'.");
        return customer;
    }

    public RoomGroup CreateRoomGroup(string groupName, RoomType type, FeePolicy fee)
    {
        ArgumentNullException.ThrowIfNull(fee);
        var id = GenerateId("RG", _roomGroups.Select(g => g.GroupId));
        var group = new RoomGroup(groupName, id, type, fee);
        if (!AddRoomGroup(group))
            throw new InvalidOperationException($"Could not register generated room-group ID '{id}'.");
        return group;
    }

    public Utility CreateUtility(string utilityName, double utilityPrice)
    {
        var id = GenerateId("UT", _utilities.Select(u => u.UtilityId));
        var utility = new Utility(utilityName, id, utilityPrice);
        if (!AddUtility(utility))
            throw new InvalidOperationException($"Could not register generated utility ID '{id}'.");
        return utility;
    }

    public Room CreateRoom(
        string roomLocation,
        int roomCapacity,
        RoomGroup roomGroup,
        RoomStatus status,
        double roomPrice)
    {
        ArgumentNullException.ThrowIfNull(roomGroup);
        if (!_roomGroups.Any(g => object.ReferenceEquals(g, roomGroup)))
            throw new ArgumentException("Room group must first be registered with this hotel service.", nameof(roomGroup));

        var id = GenerateId("R", _rooms.Select(r => r.RoomId));
        var room = new Room(roomLocation, id, roomCapacity, roomGroup, status, roomPrice);
        if (!AddRoom(room))
            throw new InvalidOperationException($"Could not register generated room ID '{id}'.");
        return room;
    }

    // ---------- Add methods with PK-like in-memory ID validation ----------

    public bool AddCustomer(Customer customer)
    {
        if (customer is null || string.IsNullOrWhiteSpace(customer.Id))
        {
            Console.WriteLine("Customer and customer ID cannot be null or blank");
            return false;
        }

        if (_customers.Any(c => string.Equals(c.Id, customer.Id, StringComparison.Ordinal)))
        {
            Console.WriteLine($"Customer ID already exists: {customer.Id}");
            return false;
        }

        _customers.Add(customer);
        return true;
    }

    public bool AddRoomGroup(RoomGroup roomGroup)
    {
        if (roomGroup is null || string.IsNullOrWhiteSpace(roomGroup.GroupId))
        {
            Console.WriteLine("Room group and room-group ID cannot be null or blank");
            return false;
        }

        if (_roomGroups.Any(g => string.Equals(g.GroupId, roomGroup.GroupId, StringComparison.Ordinal)))
        {
            Console.WriteLine($"Room-group ID already exists: {roomGroup.GroupId}");
            return false;
        }

        _roomGroups.Add(roomGroup);
        return true;
    }

    public bool AddUtility(Utility utility)
    {
        if (utility is null || string.IsNullOrWhiteSpace(utility.UtilityId))
        {
            Console.WriteLine("Utility and utility ID cannot be null or blank");
            return false;
        }

        if (_utilities.Any(u => string.Equals(u.UtilityId, utility.UtilityId, StringComparison.Ordinal)))
        {
            Console.WriteLine($"Utility ID already exists: {utility.UtilityId}");
            return false;
        }

        _utilities.Add(utility);
        return true;
    }

    public bool AddRoom(Room room)
    {
        if (room is null || string.IsNullOrWhiteSpace(room.RoomId))
        {
            Console.WriteLine("Room and room ID cannot be null or blank");
            return false;
        }

        if (_rooms.Any(r => string.Equals(r.RoomId, room.RoomId, StringComparison.Ordinal)))
        {
            Console.WriteLine($"Room ID already exists: {room.RoomId}");
            return false;
        }

        _rooms.Add(room);
        return true;
    }

    private static string GenerateId(string prefix, IEnumerable<string> existingIds)
    {
        var maxNumber = existingIds
            .Where(id => id.StartsWith(prefix, StringComparison.Ordinal))
            .Select(id => id.Substring(prefix.Length))
            .Where(s => int.TryParse(s, out _))
            .Select(int.Parse)
            .DefaultIfEmpty(0)
            .Max();

        return $"{prefix}{maxNumber + 1:D3}";
    }
    // ---------- Find operations ----------

    public Customer? FindCustomer(string customerId) =>
        _customers.FirstOrDefault(c => c.Id == customerId);

    public RoomGroup? FindRoomGroup(string roomGroupId) =>
        _roomGroups.FirstOrDefault(g => g.GroupId == roomGroupId);

    public Utility? FindUtility(string utilityId) =>
        _utilities.FirstOrDefault(u => u.UtilityId == utilityId);

    public List<RentalContract> FindOnGoingContractByCustomer(Customer customer) =>
        _contracts.Where(c => c.Customer == customer && c.Status == ContractStatus.onGoing).ToList();

    public RentalContract? FindContractById(string contractId) =>
        _contracts.FirstOrDefault(c => c.ContractId == contractId);

    public Room? FindRoom(string roomId) =>
        _rooms.FirstOrDefault(r => r.RoomId == roomId);

    // ---------- Booking workflow ----------

    public bool BookRoom(string roomId, string customerId, DateTime? startTime, DateTime? endTime)
    {
        if (startTime is null || endTime is null)
        {
            Console.WriteLine("Start time or end time cannot be null");
            return false;
        }

        if (startTime.Value >= endTime.Value)
        {
            Console.WriteLine("Invalid start time or end time");
            return false;
        }

        var customer = FindCustomer(customerId);
        var room = FindRoom(roomId);

        if (customer is null)
        {
            Console.WriteLine("Customer not found");
            return false;
        }

        if (room is null)
        {
            Console.WriteLine("Room not found");
            return false;
        }

        if (room.Status != RoomStatus.AVAILABLE)
        {
            Console.WriteLine("Room is already booked");
            return false;
        }

        room.SetRoomStatus(RoomStatus.BOOKED);
        var contract = new RentalContract(
            $"C{_contractCounter++}", customer, room, startTime.Value, endTime.Value);
        _contracts.Add(contract);
        Console.WriteLine($"Room booked successfully. Contract ID: {contract.ContractId}");
        return true;
    }

    public bool CheckIn(string contractId, DateTime? checkInTime, int numberOfPeople)
    {
        var contract = FindContractById(contractId);
        if (contract is null)
        {
            Console.WriteLine("Contract not found");
            return false;
        }

        if (contract.CheckInTime is not null)
        {
            Console.WriteLine("Customer has already checked in");
            return false;
        }

        if (contract.Status != ContractStatus.onGoing)
        {
            Console.WriteLine("Contract is already completed");
            return false;
        }

        if (checkInTime is null)
        {
            Console.WriteLine("Check-in time cannot be null");
            return false;
        }

        if (checkInTime.Value < contract.StartTime || checkInTime.Value > contract.EndTime)
        {
            Console.WriteLine("Invalid check-in time");
            return false;
        }

        if (numberOfPeople <= 0)
        {
            Console.WriteLine("Number of people must be greater than 0");
            return false;
        }

        contract.SetCheckInTime(checkInTime.Value);
        contract.SetRoomCapacityUsed(numberOfPeople);
        return true;
    }

    public bool UseUtility(string contractId, Utility? utility)
    {
        var contract = FindContractById(contractId);
        if (contract is null)
        {
            Console.WriteLine("Contract not found");
            return false;
        }

        if (contract.Status != ContractStatus.onGoing)
        {
            Console.WriteLine("Contract is not ongoing");
            return false;
        }

        if (contract.CheckInTime is null || contract.CheckOutTime is not null)
        {
            Console.WriteLine("Customer is not checked in");
            return false;
        }

        if (utility is null)
        {
            Console.WriteLine("Utility cannot be null");
            return false;
        }

        contract.AddUtility(utility);
        return true;
    }

    public bool CheckOut(string contractId, DateTime? checkOutTime)
    {
        var contract = FindContractById(contractId);
        if (contract is null)
        {
            Console.WriteLine("Contract not found");
            return false;
        }

        if (contract.CheckInTime is null)
        {
            Console.WriteLine("Customer has not checked in");
            return false;
        }

        if (contract.Status != ContractStatus.onGoing)
        {
            Console.WriteLine("Contract is already completed");
            return false;
        }

        if (checkOutTime is null)
        {
            Console.WriteLine("Check-out time cannot be null");
            return false;
        }

        if (checkOutTime.Value < contract.CheckInTime.Value)
        {
            Console.WriteLine("Invalid check-out time");
            return false;
        }

        contract.SetCheckOutTime(checkOutTime.Value);
        contract.EndContract();
        contract.Room.SetRoomStatus(RoomStatus.AVAILABLE);
        return true;
    }

    // ---------- Billing ----------

    public double CalculateRoomFee(RentalContract contract)
    {
        ArgumentNullException.ThrowIfNull(contract);
        if (contract.CheckOutTime is null)
            return 0;

        var days = (contract.CheckOutTime.Value.Date - contract.StartTime.Date).Days;
        return (double)days * contract.Room.RoomPrice;
    }

    public double CalculateOverstayFee(RentalContract contract)
    {
        ArgumentNullException.ThrowIfNull(contract);
        if (contract.CheckOutTime is null)
            return 0;

        var days = Math.Max(0, (contract.CheckOutTime.Value.Date - contract.EndTime.Date).Days);
        return contract.Room.RoomGroup.Fee.OverStayFeePerDay * days;
    }

    public double CalculateUtilityFee(RentalContract contract)
    {
        ArgumentNullException.ThrowIfNull(contract);
        var group = contract.Room.InGroup;
        return contract.UtilitiesUsed
            .Where(u => !u.IsFreeForGroup(group))
            .Sum(u => u.UtilityPrice);
    }

    public double CalculateOverMaxCapacityFee(RentalContract contract)
    {
        ArgumentNullException.ThrowIfNull(contract);
        if (contract.CheckOutTime is null)
            return 0;

        var maxCapacity = contract.Room.RoomCapacity;
        var capacityUsed = contract.RoomCapacityUsed;
        if (capacityUsed <= maxCapacity)
            return 0;

        return (capacityUsed - maxCapacity) * contract.Room.RoomGroup.Fee.OverMaxCapacityFee;
    }

    public Invoice? CreateInvoice(RentalContract? contract, Customer? payer, PaymentType paymentType)
    {
        if (contract is null)
        {
            Console.WriteLine("Contract not found");
            return null;
        }

        if (contract.CheckOutTime is null)
        {
            Console.WriteLine("Customer has not checked out");
            return null;
        }

        if (_invoices.Any(i => i.Contract == contract))
        {
            Console.WriteLine("Invoice already exists for this contract");
            return null;
        }

        if (payer is null)
        {
            Console.WriteLine("Payer cannot be null");
            return null;
        }

        var roomFee = CalculateRoomFee(contract);
        var overstayFee = CalculateOverstayFee(contract);
        var utilityFee = CalculateUtilityFee(contract);
        var overCapacityFee = CalculateOverMaxCapacityFee(contract);
        var deposit = roomFee * 0.10;
        var total = roomFee + overstayFee + utilityFee + overCapacityFee - deposit;

        var invoice = new Invoice(
            $"I{_invoiceCounter++}", payer, contract, paymentType,
            roomFee, overstayFee, overCapacityFee, utilityFee, deposit, total);

        _invoices.Add(invoice);
        Console.WriteLine(invoice);
        return invoice;
    }
}